import React, { useState } from 'react';
import './CrearPostFlotante.css'; // Asegúrate de crear este archivo con el CSS que te di antes

const CrearPostFlotante = ({ onClose }) => {
  const [texto, setTexto] = useState('');
  const [imagenUrl, setImagenUrl] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Aquí podrías enviar los datos al backend o actualizarlos en el estado global
    console.log('Post enviado:', { texto, imagenUrl });
    // Limpia y cierra
    setTexto('');
    setImagenUrl('');
    onClose();
  };

  return (
    <div className="crear-post-float">
      <div className="crear-post-contenedor">
        <div className="crear-post-header">
          <h5>[Crear Post]</h5>
          <button className="btn-x-post" onClick={onClose}>
            <i className="bi bi-x-circle"></i>
          </button>
        </div>

        <form className="crear-post-body" onSubmit={handleSubmit}>
          <div className="crear-post-text">
            <h5>Texto</h5>
          </div>
          <div className="crear-post-area">
            <textarea
              name="text-post"
              value={texto}
              onChange={(e) => setTexto(e.target.value)}
              required
            />
          </div>

          <div className="crear-post-imagen">
            <h5>Imagen</h5>
            <input
              type="text"
              value={imagenUrl}
              onChange={(e) => setImagenUrl(e.target.value)}
              placeholder="URL de la imagen"
            />
          </div>

          <button type="submit" className="btn-publicar">Post</button>
        </form>
      </div>
    </div>
  );
};

export default CrearPostFlotante;
